CREATE TABLE IF NOT EXISTS collections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,short_description TEXT NULL,long_description MEDIUMTEXT NULL,cover_media_id BIGINT UNSIGNED NULL,hero_media_id BIGINT UNSIGNED NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,is_featured TINYINT(1) NOT NULL DEFAULT 0,seo_title VARCHAR(255) NULL,meta_description VARCHAR(500) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX(status),INDEX(sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS subcollections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,collection_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL,description TEXT NULL,cover_media_id BIGINT UNSIGNED NULL,hero_media_id BIGINT UNSIGNED NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,seo_title VARCHAR(255) NULL,meta_description VARCHAR(500) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY unique_subcollection_slug(collection_id,slug),FOREIGN KEY(collection_id) REFERENCES collections(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,collection_id BIGINT UNSIGNED NOT NULL,subcollection_id BIGINT UNSIGNED NULL,name VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,short_description TEXT NULL,long_description MEDIUMTEXT NULL,technical_details MEDIUMTEXT NULL,main_media_id BIGINT UNSIGNED NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',is_featured TINYINT(1) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,seo_title VARCHAR(255) NULL,meta_description VARCHAR(500) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(collection_id) REFERENCES collections(id),FOREIGN KEY(subcollection_id) REFERENCES subcollections(id) ON DELETE SET NULL,INDEX(status),INDEX(is_featured)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,media_id BIGINT UNSIGNED NOT NULL,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,INDEX(product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS applications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,description TEXT NULL,content MEDIUMTEXT NULL,main_media_id BIGINT UNSIGNED NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,seo_title VARCHAR(255) NULL,meta_description VARCHAR(500) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS application_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NOT NULL,media_id BIGINT UNSIGNED NOT NULL,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,uuid CHAR(36) NOT NULL UNIQUE,original_name VARCHAR(255) NOT NULL,path VARCHAR(500) NOT NULL UNIQUE,mime_type VARCHAR(120) NOT NULL,file_size BIGINT UNSIGNED NOT NULL,alt_text VARCHAR(255) NULL,usage_context VARCHAR(120) NULL,uploaded_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(mime_type),FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(150) PRIMARY KEY,`value` MEDIUMTEXT NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS contact_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(190) NULL,subject VARCHAR(200) NULL,message MEDIUMTEXT NULL,related_type VARCHAR(50) NULL,related_id BIGINT UNSIGNED NULL,status VARCHAR(30) NOT NULL DEFAULT 'new',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL,INDEX(status),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
